PRAGMA foreign_keys = ON;
CREATE TABLE case_studies (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL, summary TEXT NOT NULL, challenge TEXT NOT NULL, solution TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','published','archived')), permission_status TEXT NOT NULL DEFAULT 'pending' CHECK(permission_status IN('pending','authorized','withdrawn')), evidence_source TEXT, published_at TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE case_study_claims (id TEXT PRIMARY KEY, case_study_id TEXT NOT NULL REFERENCES case_studies(id) ON DELETE CASCADE, label TEXT NOT NULL, value TEXT NOT NULL, evidence_level TEXT NOT NULL CHECK(evidence_level IN('platform-recorded','document-supported','participant-confirmed','member-reported','illustrative')), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE case_study_evidence (id TEXT PRIMARY KEY, case_study_id TEXT NOT NULL REFERENCES case_studies(id) ON DELETE CASCADE, object_key TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', is_public INTEGER NOT NULL DEFAULT 0, permission_confirmed INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')));
